import{_ as a,o as e,c as n,a4 as s}from"./chunks/framework.B0hSrcZ6.js";const l="/info/03-install.webp",r="/info/03-install-s2.webp",o="/info/03-install-s6.webp",i="/info/03-install-s8.webp",b=JSON.parse('{"title":"第 3 章 安装登录与第一个 Bot","description":"本章介绍 Grok Bot 的双端安装、登录排查与环境配置。指导新手基于共享底座创建专属智能体，通过标准六行合同明确职责范围，顺利派发并验收首条落盘任务。","frontmatter":{},"headers":[],"relativePath":"part1/03-install.md","filePath":"part1/03-install.md","lastUpdated":1792419518000}'),p={name:"part1/03-install.md"};function c(d,t,h,g,u,k){return e(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="第-3-章-安装登录与第一个-bot" tabindex="-1">第 3 章 安装登录与第一个 Bot <a class="header-anchor" href="#第-3-章-安装登录与第一个-bot" aria-label="Permalink to &quot;第 3 章 安装登录与第一个 Bot&quot;">​</a></h1><p><strong>确认订阅含 Bot 权益</strong>，不然没入口；登录跳循环查隐私设置。别建无约束的“全能助手”白耗周配额。</p><ol><li>装好桌面与移动端，排除登录报错</li><li><strong>建专属 Bot 填六行合同</strong></li><li>派发首条落盘任务，对照清单验收</li></ol><p><img src="'+l+'" alt="安装登录与第一个 Bot" width="1600" height="1013" decoding="async"></p><h2 id="订阅方案核对与开通条件" tabindex="-1">订阅方案核对与开通条件 <a class="header-anchor" href="#订阅方案核对与开通条件" aria-label="Permalink to &quot;订阅方案核对与开通条件&quot;">​</a></h2><p>下载前先看账号资格，<strong>Grok Bot 必须绑定有效订阅才能用</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方案名称</th><th style="text-align:left;">价格</th><th style="text-align:left;">是否包含 Grok Bot</th><th style="text-align:left;">额度说明</th></tr></thead><tbody><tr><td style="text-align:left;">The X Plus</td><td style="text-align:left;">$8 / 月</td><td style="text-align:left;">否</td><td style="text-align:left;">仅普通模型对话，无 Bot 权限</td></tr><tr><td style="text-align:left;">The X Premium</td><td style="text-align:left;">$30 / 月（年付 $300）</td><td style="text-align:left;">是</td><td style="text-align:left;">4x 额度，个人入门最低门槛</td></tr><tr><td style="text-align:left;">The X Super</td><td style="text-align:left;">$100 / 月（年付 $1000）</td><td style="text-align:left;">是</td><td style="text-align:left;">15x 额度</td></tr><tr><td style="text-align:left;">The X Ultra</td><td style="text-align:left;">$200 / 月（年付 $2000）</td><td style="text-align:left;">是</td><td style="text-align:left;">50x 额度</td></tr><tr><td style="text-align:left;">Cursor Pro / Pro+ / Ultra</td><td style="text-align:left;">见官网定价</td><td style="text-align:left;">是</td><td style="text-align:left;">依档位提供每周额度</td></tr><tr><td style="text-align:left;">Cursor Teams (自助席位)</td><td style="text-align:left;">见官网定价</td><td style="text-align:left;">是</td><td style="text-align:left;">成员共享团队配额</td></tr></tbody></table><ul><li><strong>每月 8 美元的 Plus 档不包含 Bot 权益</strong>，买了用不了。</li><li><strong>X 关联额度与 Cursor 订阅额度不叠加</strong>，系统结算自动按每周用量更高的一方算。</li></ul><p>方案底座机制参考社区文章 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/I04Gw3wEaisftUkBikxcg43rnpc" target="_blank" rel="noreferrer">《1.1 Grok Bot 是什么：一页看懂》</a> 与 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/Zs1JwANRgiOvJ4klrADcMxJ9nzg" target="_blank" rel="noreferrer">《万文长｜Grok Bot 从零入门第一次上》</a>。</p><h2 id="桌面端下载与安装" tabindex="-1">桌面端下载与安装 <a class="header-anchor" href="#桌面端下载与安装" aria-label="Permalink to &quot;桌面端下载与安装&quot;">​</a></h2><p><img src="'+r+'" alt="桌面端下载与安装" width="1600" height="1013" loading="lazy" decoding="async"></p><p>macOS 支持 Apple silicon（M 系列）与 Intel，Windows 和 Linux 支持 x64 与 Arm64（Win 建议开硬件加速）。</p><ol><li>登录 <code>cursor.com/dashboard/bot</code> 或直接去 <code>x.ai/bot</code> 下载安装包。<strong>若公司设备无权限，找管理员索取</strong>。</li><li>macOS 把下载的应用拖进 <code>Applications</code> 文件夹，Windows 和 Linux 跑安装向导。</li><li><strong>启动客户端看到登录界面就成了</strong>。具体操作可参考文档 <a href="https://cursor.com/cn/docs/grok-bot/get-started" target="_blank" rel="noreferrer">Grok Bot 快速入门</a>。</li></ol><h2 id="账号登录与隐私模式配置" tabindex="-1">账号登录与隐私模式配置 <a class="header-anchor" href="#账号登录与隐私模式配置" aria-label="Permalink to &quot;账号登录与隐私模式配置&quot;">​</a></h2><ol><li>启动客户端点 <strong>登录</strong>，在浏览器直接用 Cursor 账号认证，企业 SSO 会自动生效；如果是 Grok Business 席位，选 <strong>Sign in with Grok</strong> 登录。</li><li>认证完成后进客户端“设置”，能看到账号邮箱和方案状态就说明成功了。</li></ol><p><strong>旧版隐私模式（Privacy Mode (Legacy)）必须切到现行 Privacy Mode 才能继续</strong>。个人用户在弹窗点确认即可；团队成员需要让管理员去 Team Settings 里更新。</p><p>详细说明参考官方文档 <a href="https://cursor.com/cn/help/grok-bot/onboarding" target="_blank" rel="noreferrer">入职</a> 与 <a href="https://cursor.com/cn/help/grok-bot/sign-in" target="_blank" rel="noreferrer">登录 Grok Bot</a>。</p><h2 id="常见登录问题与故障排查" tabindex="-1">常见登录问题与故障排查 <a class="header-anchor" href="#常见登录问题与故障排查" aria-label="Permalink to &quot;常见登录问题与故障排查&quot;">​</a></h2><p>盲目重装没用，多是缓存或会话刷新问题。</p><ol><li>客户端升至最新并重登。</li><li>清 <code>cursor.com</code> 与 <code>x.ai</code> 的 Cookie 或用无痕模式。</li><li>登 <code>x.ai/bot</code> 确认网页端能建立会话。</li><li>刚改订阅<strong>静置等 30 至 60 分钟</strong>，刷新后报错消除。</li></ol><p>手机验证连错会触发风控锁定，无法自愈。排查无效或遇 OAuth 报错，<strong>去支持页提工单</strong>，附邮箱与截图，写明版本及步骤。</p><p>详见 <a href="https://cursor.com/cn/help/grok-bot/sign-in" target="_blank" rel="noreferrer">登录 Grok Bot</a>。</p><h2 id="ios-移动端安装与双端协同" tabindex="-1">iOS 移动端安装与双端协同 <a class="header-anchor" href="#ios-移动端安装与双端协同" aria-label="Permalink to &quot;iOS 移动端安装与双端协同&quot;">​</a></h2><h3 id="安装与登录" tabindex="-1">安装与登录 <a class="header-anchor" href="#安装与登录" aria-label="Permalink to &quot;安装与登录&quot;">​</a></h3><ol><li>系统需 <strong>iOS 18 或更高版本</strong>。</li><li>App Store 搜 Grok Bot 安装，登录同个 Cursor 账号自动同步，<strong>无需重复付费</strong>。</li></ol><h3 id="双端分工" tabindex="-1">双端分工 <a class="header-anchor" href="#双端分工" aria-label="Permalink to &quot;双端分工&quot;">​</a></h3><ul><li>手机端适合日常监控，能看实时屏幕，支持接管控制（Take over）输验证码、审批（Allow / Deny）或启停 Routine。</li><li><strong>深度操作必须回桌面端</strong>：最长 10 分钟录屏教学（Teach a task）、测试 Routine（Test run）与维护云电脑（Update / Recover）。</li></ul><h3 id="通知管理" tabindex="-1">通知管理 <a class="header-anchor" href="#通知管理" aria-label="Permalink to &quot;通知管理&quot;">​</a></h3><ul><li><strong>单个 Bot 静音</strong>：聊天页点顶部名字关闭 <strong>Notifications</strong>，桌面端发消息也能关。</li><li><strong>全局关闭</strong>：在系统“设置”中关闭 Grok Bot 的通知权限。</li></ul><p>详见 <a href="https://cursor.com/cn/help/grok-bot/mobile" target="_blank" rel="noreferrer">移动端 Grok Bot</a>。</p><h2 id="认识共享底座与创建第一个-bot" tabindex="-1">认识共享底座与创建第一个 Bot <a class="header-anchor" href="#认识共享底座与创建第一个-bot" aria-label="Permalink to &quot;认识共享底座与创建第一个 Bot&quot;">​</a></h2><p><img src="'+o+`" alt="认识共享底座与创建第一个 Bot" width="1600" height="1013" loading="lazy" decoding="async"></p><p>每个付费用户都有一台常驻云端虚拟机，配置独立 Linux、浏览器、终端与持久磁盘（早期测试配置约 8 核 16GB 内存，未核实，具体以官方为准）。</p><p>这台机器有三个直接影响操作的物理边界：</p><ul><li><strong>所有 Bot 共享同一台机器</strong>：共用 <code>/workspace</code> 与一套浏览器登录态，分设 Bot 只是划分岗位，没有安全隔离。</li><li><strong>跨 Bot 协作必须文件落盘</strong>：聊天记录互不相通，Bot A 必须把产物写进 <code>/workspace</code> 文件，Bot B 才能读取接力。</li><li><strong>支持随时查看与实时接管</strong>：右侧可展开云电脑画面，遇到密码、人机验证或支付认证随时接管，不要把凭证打在输入框里。</li></ul><p>首次登录会自动生成默认的 <strong>Grok Bot</strong>，手动新建与设置步骤如下：</p><ol><li><strong>新建</strong>：点侧边栏顶部 <strong>+</strong>（或 Cmd+N），选 <strong>创建新 Bot</strong>（Create new Bot）。在输入框先输名字也能直接点击创建。</li><li><strong>改名与标签</strong>：右键选 <strong>重命名机器人</strong>，或点顶部名称展开面板修改。下方可设职务标签（Label，手机端为 Title (optional)）。</li><li><strong>换头像</strong>：点击顶部名称进详情并点击头像，支持选择内置几何图形、输入描述词生成，或上传 25 MB 以内的本地图片（手机端可选相册、生成或移除）。</li><li><strong>设职责</strong>：<strong>个人 Bot 已取消独立设置页，长期规则直接在首条消息说明并要求它记住</strong>。团队 Bot 在详情“关于”栏仍保留固定描述区。</li></ol><ul><li><a href="https://cursor.com/cn/help/grok-bot/edit-bot" target="_blank" rel="noreferrer">更改 Bot 的名称、头像和职责</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MIKpwiUXpiE9mWkyG8ccFM6Znee" target="_blank" rel="noreferrer">《万字长文｜Grok Bot 从入门到精通｜金尘马》</a></li></ul><h2 id="编写职责-标准六行合同" tabindex="-1">编写职责：标准六行合同 <a class="header-anchor" href="#编写职责-标准六行合同" aria-label="Permalink to &quot;编写职责：标准六行合同&quot;">​</a></h2><h3 id="合同结构与模板" tabindex="-1">合同结构与模板 <a class="header-anchor" href="#合同结构与模板" aria-label="Permalink to &quot;合同结构与模板&quot;">​</a></h3><p>新手别给空泛头衔，<strong>把六项核心约束直接写进第一条消息</strong>，让它当成长期规则记住。</p><ol><li>Own（负责结果）：明确长期负责的具体指标，不做泛用助手。</li><li>Sources（权威来源）：限定只看官网或指定链接，禁止使用不明信源。</li><li>Output（交付格式）：规定保存路径、命名规则和摘要字数。</li><li>Approval（审批红线）：发信、提交表单或删文件等高危操作，必须等人工弹窗批准。</li><li>Failure（异常兜底）：遇到网页失效或数据缺失，必须明确标注，严禁脑补推测。</li><li>Never（绝对禁区）：禁止改动源文件，禁止凭记忆概述，禁止点击付款按钮。</li></ol><p>Bot 命名好后，替换模版字段直接发送。</p><details class="details custom-block"><summary>合同结构与模板</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请牢记你的长期工作职责，在今后的工作中始终遵循以下要求：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Own: 负责监控目标清单的每周功能与定价变动，输出结构化对比材料。</span></span>
<span class="line"><span>Sources: 仅限使用目标官方网站的定价页、Changelog 页面以及我通过附件提供的官方说明文档。</span></span>
<span class="line"><span>Output: 提炼核心动态，附带核对日期与原始出处链接，长文本与数据表格必须保存至 /workspace/research/ 下的 Markdown 文件中，对话框中只发简要完成汇报。</span></span>
<span class="line"><span>Approval: 涉及发送任何邮件、对外发帖、提交表单、删除文件或进行任何费用支付前，必须停下来等待我的人工批准。</span></span>
<span class="line"><span>Failure: 若目标页面无法访问或内容缺失，在报告中明确标注为“未取得一手数据”，严禁推测或编造任何功能与价格。</span></span>
<span class="line"><span>Never: 严禁修改我上传的任何源文件，在源系统可访问时严禁依赖自身训练记忆进行主观概括。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>今后的工作中请记住这些要求。</span></span></code></pre></div></details><h3 id="实践案例" tabindex="-1">实践案例 <a class="header-anchor" href="#实践案例" aria-label="Permalink to &quot;实践案例&quot;">​</a></h3><ul><li><p>金尘马在 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/MIKpwiUXpiE9mWkyG8ccFM6Znee" target="_blank" rel="noreferrer">《万字长文｜Grok Bot 从入门到精通｜金尘马》</a> 中，<strong>把长期职责与单次需求严格分开</strong>。</p><p>长期规则管信源和交付，当次消息只派具体调研主题；缺一手数据直接说明，严禁猜数字。</p></li><li><p>Today 在 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/Zs1JwANRgiOvJ4klrADcMxJ9nzg" target="_blank" rel="noreferrer">《万文长｜Grok Bot 从零入门第一次上》</a> 中设置了安全边界，<strong>将只读与有外部后果的操作隔离开</strong>。</p><p>每次只调研一个竞品并附带公开来源链接，分清事实与推测；涉及登录付款一律停下等确认。</p></li></ul><p>演化规则参阅 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/I04Gw3wEaisftUkBikxcg43rnpc" target="_blank" rel="noreferrer">《1.1 Grok Bot 是什么：一页看懂》</a>。</p><h2 id="派发第一条真实任务" tabindex="-1">派发第一条真实任务 <a class="header-anchor" href="#派发第一条真实任务" aria-label="Permalink to &quot;派发第一条真实任务&quot;">​</a></h2><p><img src="`+i+`" alt="派发第一条真实任务" width="1600" height="1013" loading="lazy" decoding="async"></p><p><strong>先从小任务上手</strong>。写任务记好 5 要素：讲清目标与输入，严格只读（禁改源文件、注册与支付），定好落盘规格，标明接管节点。</p><p>附件总结发：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用五个要点总结这份文档。</span></span>
<span class="line"><span>在单独的部分列出每个日期、决策和未解决的问题，并为每项注明对应章节出处。</span></span>
<span class="line"><span>不要更改源文件。</span></span></code></pre></div><p>查竞品定价落盘发：</p><details class="details custom-block"><summary>派发第一条真实任务</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【目标】</span></span>
<span class="line"><span>调研 3 款主流代码编辑器（Cursor、VS Code、Zed）在 2026 年的最新公开定价方案与核心 AI 功能，产出一份选型对比参考材料。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【材料】</span></span>
<span class="line"><span>1. 仅限使用上述三款产品官方网站的定价页、功能介绍页与官方文档；第三方博客仅作为辅助索引，必须找到官方页面核实。</span></span>
<span class="line"><span>2. 记录每一项数据的原始官方 URL 与数据核对日期。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【边界】</span></span>
<span class="line"><span>1. 纯只读检索，严禁注册任何账号，严禁开启任何试用，严禁输入任何支付信息。</span></span>
<span class="line"><span>2. 遇到需要登录才能查看的页面，直接跳过并记录在未核实清单中。</span></span>
<span class="line"><span>3. 严禁改动 /workspace 下已有的其他项目文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【交付规格】</span></span>
<span class="line"><span>1. 在 /workspace/editor-research/ 目录下生成对比报告文件 comparison.md。</span></span>
<span class="line"><span>2. 报告内包含一张 Markdown 数据表格，表头列定义为：产品名称、方案档位、月付价格、年付价格、核心功能特征、官网来源链接、核对日期。</span></span>
<span class="line"><span>3. 表格下方附带一份 400 字以内的中文总结，指出各产品主要差异，并单独开辟一节列出“未核实或存在矛盾的信息”。</span></span>
<span class="line"><span>4. 对话框中仅需回复已完成落盘的简短提示及文件绝对路径。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【暂停确认节点】</span></span>
<span class="line"><span>1. 遇到必须登录、验证码拦截或点击付费的操作时，立刻停下并提示我接管。</span></span>
<span class="line"><span>2. 官网信息前后出现明显矛盾且无法核实时，停下说明情况由我判断。</span></span></code></pre></div></details><p>遇登录、2FA 或滑块验证时：</p><ol><li><strong>点 Take over 手动处理</strong>，弄完点 I&#39;m done 继续，跳过点 Skip。</li><li>跑完<strong>确认 <code>/workspace/editor-research/comparison.md</code> 完整保存</strong>。</li></ol><p>规范见 <a href="https://cursor.com/cn/docs/grok-bot/get-started" target="_blank" rel="noreferrer">使用 Grok Bot</a> 与 <a href="https://cursor.com/cn/help/grok-bot/onboarding" target="_blank" rel="noreferrer">入职</a>。</p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li>8 美元 Plus 档没 Bot，<strong>必须选每月 30 美元的 Premium 档</strong>。</li><li>所有 Bot 共享云电脑与配额，先跑通一个，别建十几个互相打架。</li><li>别在聊天框发密码或 API Key，用 Take over 接管输入或填安全卡片。</li><li>长文本<strong>一律存入 <code>/workspace</code> 的 Markdown 文件</strong>，防污染上下文。</li><li>登录报错别重装，清理 <code>cursor.com</code> 和 <code>x.ai</code> 的 Cookie，或等 30 至 60 分钟。</li><li><strong>不同 Bot 共享虚拟机和浏览器会话</strong>，不能隔离权限。</li><li>Teach a task、Test run 和系统恢复是桌面端独有，iOS 端没有。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li>进 Usage &amp; Billing，付费档有效、用量正常。</li><li>桌面端右屏能拉起，无 Reconnecting 报错。</li><li>iPhone（iOS 18+）登相同 Cursor 账号，无二次购买提示。</li><li>发六行合同，Bot 明确回复已记住长期规则。</li><li>云电脑 <code>/workspace</code> 按指令生成目标文件。</li><li>遇登录等操作，Bot 主动暂停并弹 <strong>Action needed</strong> 卡片。</li><li>故意喂死链，报告明确标注 <strong>未取得一手数据</strong>、不瞎编。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h3><ul><li><a href="/part1/04-handoff">第 4 章 交代任务：消息、附件与一次好的交接</a></li><li><a href="/part4/25-faq">第 25 章 常见问题与排错</a></li></ul><h3 id="官方页面" tabindex="-1">官方页面 <a class="header-anchor" href="#官方页面" aria-label="Permalink to &quot;官方页面&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/docs/grok-bot/get-started" target="_blank" rel="noreferrer">Grok Bot 快速入门 (Get Started)</a></li><li><a href="https://cursor.com/cn/help/grok-bot/onboarding" target="_blank" rel="noreferrer">入职 (Onboarding)</a></li><li><a href="https://cursor.com/cn/help/grok-bot/sign-in" target="_blank" rel="noreferrer">登录 Grok Bot (Sign In)</a></li><li><a href="https://cursor.com/cn/help/grok-bot/mobile" target="_blank" rel="noreferrer">移动端 Grok Bot (Mobile)</a></li><li><a href="https://cursor.com/cn/help/grok-bot/edit-bot" target="_blank" rel="noreferrer">更改 Bot 的名称、头像和职责 (Edit Bot)</a></li></ul><h3 id="社区实战" tabindex="-1">社区实战 <a class="header-anchor" href="#社区实战" aria-label="Permalink to &quot;社区实战&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/I04Gw3wEaisftUkBikxcg43rnpc" target="_blank" rel="noreferrer">《1.1 Grok Bot 是什么：一页看懂》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MIKpwiUXpiE9mWkyG8ccFM6Znee" target="_blank" rel="noreferrer">《万字长文｜Grok Bot 从入门到精通｜金尘马》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Zs1JwANRgiOvJ4klrADcMxJ9nzg" target="_blank" rel="noreferrer">《万文长｜Grok Bot 从零入门第一次上》</a></li></ul>`,68)])])}const m=a(p,[["render",c]]);export{b as __pageData,m as default};
